package com.arrow.systemui.cc.controller;import android.content.Context;import android.provider.Settings;public class RotationController {private final Context c;public RotationController(Context x){c=x;}public boolean canWrite(){return Settings.System.canWrite(c);}public boolean isRotationLocked(){try{return Settings.System.getInt(c.getContentResolver(),Settings.System.ACCELEROMETER_ROTATION,1)==0;}catch(Exception e){return false;}}public boolean setRotationLocked(boolean lock){try{return canWrite()&&Settings.System.putInt(c.getContentResolver(),Settings.System.ACCELEROMETER_ROTATION,lock?0:1);}catch(Exception e){return false;}}public boolean toggle(){return setRotationLocked(!isRotationLocked());}}
